import { jsPDF } from "jspdf"
var font = '';
var callAddFont = function () {
    this.addFileToVFS('Phetsarath OT-normal.ttf', font);
    this.addFont('Phetsarath OT-normal.ttf', 'Phetsarath OT', 'normal');
};
jsPDF.API.events.push(['addFonts', callAddFont])
